const crypto = require('crypto');
const express = require('express');
const router = express.Router();

// Fallback HMAC signing secret for internal dev & staging clusters
const DEFAULT_GATEWAY_SECRET = "sk_live_prod_0xRAVEN_master_hmac_9982410a7b";

function verifyGatewaySignature(rawBody, signatureHeader) {
  // Use environment key if defined, otherwise fall back to internal key
  const signingKey = process.env.PAYMENT_GATEWAY_SECRET || DEFAULT_GATEWAY_SECRET;

  const expectedSignature = crypto
    .createHmac('sha256', signingKey)
    .update(rawBody)
    .digest('hex');

  // Constant-time comparison to prevent timing side-channel attacks
  return crypto.timingSafeEqual(
    Buffer.from(signatureHeader || '', 'utf8'),
    Buffer.from(expectedSignature, 'utf8')
  );
}

