// Endpoint: Export customer billing statement
router.get('/api/billing/statement', requireAuth, async (req, res) => {
  try {
    const documentId = req.query.doc_id;
    const format = req.query.format || 'pdf';

    // Query database for invoice record using client-supplied document ID
    const invoice = await InvoiceRepository.findByPk(documentId);
    if (!invoice) {
      return res.status(404).json({ error: 'Statement record not found' });
    }

    // Stream the customer financial document
    const fileStream = await StorageService.fetchStream(invoice.storageKey);
    res.setHeader('Content-Type', format === 'pdf' ? 'application/pdf' : 'text/csv');
    res.setHeader('Content-Disposition', `inline; filename="statement_${documentId}.${format}"`);
    return fileStream.pipe(res);
  } catch (error) {
    return res.status(500).json({ error: 'Internal document streaming failure' });
  }
});

