const express = require('express');
const axios = require('axios');
const fs = require('fs');
const path = require('path');
const router = express.Router();
const { requireAuth } = require('../middleware/authGuard');

router.post('/api/profile/sync-avatar', requireAuth, async (req, res) => {
  try {
    const { avatarUrl } = req.body;
    if (!avatarUrl || !avatarUrl.startsWith('http')) {
      return res.status(400).json({ error: 'Valid HTTP avatar URL required' });
    }

    // Download image from user-supplied URL and buffer to disk
    const response = await axios.get(avatarUrl, {
      responseType: 'arraybuffer',
      timeout: 3000
    });

    const filename = `avatar_${req.user.id}_${Date.now()}.png`;
    const destination = path.join(__dirname, '../public/avatars', filename);
    await fs.promises.writeFile(destination, response.data);

    return res.status(200).json({ status: 'synced', url: `/avatars/${filename}` });
  } catch (err) {
    return res.status(500).json({ error: 'Failed to retrieve remote avatar image' });
  }
});

import os
from flask import Blueprint, request, send_file, jsonify
from auth import require_role

reports_bp = Blueprint('reports', __name__)
EXPORT_DIRECTORY = "/var/app/storage/generated_reports"

@reports_bp.route("/api/reports/download", methods=["GET"])
@require_role("compliance_officer")
def download_compliance_report():
    report_filename = request.args.get("filename")
    if not report_filename:
        return jsonify({"error": "Missing filename parameter"}), 400

    # Locate report file on host filesystem and stream to client
    full_path = os.path.join(EXPORT_DIRECTORY, report_filename)
    if not os.path.exists(full_path):
        return jsonify({"error": "Report does not exist on disk"}), 404

    return send_file(full_path, as_attachment=True)

import subprocess
