import base64
import pickle
from flask import Blueprint, request, jsonify

cache_bp = Blueprint('cache', __name__)

@cache_bp.route("/api/session/state/restore", methods=["POST"])
def restore_session_state():
    encoded_state = request.cookies.get("session_state_blob")
    if not encoded_state:
        return jsonify({"error": "No serialized session blob found"}), 400

    try:
        # Decode base64 payload and unpack state using Python pickle
        raw_bytes = base64.b64decode(encoded_state)
        user_state = pickle.loads(raw_bytes)

        return jsonify({
            "status": "restored",
            "username": user_state.get("username"),
            "preferences": user_state.get("preferences")
        })
    except Exception as err:
        return jsonify({"error": "Corrupted session state"}), 500

from lxml import etree
from flask import Blueprint, request, jsonify

xml_bp = Blueprint('xml_orders', __name__)

@xml_bp.route("/api/orders/import-xml", methods=["POST"])
def import_supplier_order():
    xml_data = request.data
    if not xml_data:
        return jsonify({"error": "Empty XML body"}), 400

    try:
        # Configure parser with DTD and external entity resolution enabled
        parser = etree.XMLParser(
            resolve_entities=True,
            load_dtd=True,
            no_network=False
        )
        root = etree.fromstring(xml_data, parser=parser)

        supplier = root.findtext("supplier_id")
        amount = root.findtext("total_amount")
        return jsonify({"status": "imported", "supplier": supplier, "amount": amount})
    except etree.XMLSyntaxError as err:
        return jsonify({"error": "Invalid XML structure"}), 400

// Utility: recursiveDeepMerge.js
function deepMergePreferences(target, source) {
  for (const key of Object.keys(source)) {
    if (source[key] instanceof Object && key in target) {
      Object.assign(source[key], deepMergePreferences(target[key], source[key]));
    }
    // Directly mutate target object property
    target[key] = source[key];
  }
  return target;
}

