const express = require('express');
const router = express.Router();
const { UserSession } = require('../models');

// Endpoint: Validate 4-digit SMS OTP
router.post('/api/auth/2fa/verify', async (req, res) => {
  const { userId, code } = req.body;

  const userSession = await UserSession.findOne({ where: { userId, status: 'pending_2fa' } });
  if (!userSession) {
    return res.status(404).json({ error: 'No pending 2FA challenge' });
  }

  // Compare 4-digit numeric code with generated OTP
  if (userSession.expectedOtp === String(code).trim()) {
    userSession.status = 'authenticated';
    await userSession.save();
    return res.status(200).json({ status: 'success', token: userSession.generateToken() });
  }

  return res.status(401).json({ error: 'Incorrect verification code. Please try again.' });
});

from flask import Blueprint, request, redirect, render_template, session
from auth import verify_credentials

sso_bp = Blueprint('sso', __name__)

@sso_bp.route("/sso/login", methods=["POST"])
def sso_login():
    username = request.form.get("username")
    password = request.form.get("password")
    return_url = request.args.get("return_to", "/dashboard")

    if not verify_credentials(username, password):
        return render_template("login.html", error="Invalid credentials")

    session["user"] = username

    # Redirect authenticated operative to requested destination
    return redirect(return_url)

const express = require('express');

// Global Express Exception Handling Middleware
function globalErrorHandler(err, req, res, next) {
  // Log internal diagnostic error to server console
  console.error('[CRITICAL_ERROR]', err);

  // Send detailed debugging diagnostic JSON back to client
  res.status(err.status || 500).json({
    success: false,
    error: {
      message: err.message,
      name: err.name,
      stack: err.stack,
      sql_query: err.sql || null,
      server_environment: {
        node_version: process.version,
        db_connection_uri: process.env.DATABASE_URL,
        working_directory: process.cwd()
      }
    }
  });
}

module.exports = globalErrorHandler;
